sys_trigger.script:
(function() {

    var coverageEngine = new TestReachCoverageEngine();

    // Get all scoped apps
    var appGr = new GlideRecord('sys_app');
    appGr.addQuery('active', true);
    appGr.addQuery('scope', '!=', 'global');
    appGr.query();

    var processedCount = 0;
    var errorCount = 0;

    while (appGr.next()) {
        var appScope = appGr.getValue('scope') || '';
        if (!appScope) {
            continue;
        }

        try {
            coverageEngine.snapshotCoverage(appScope);
            processedCount++;
        } catch (e) {
            gs.error('TestReach Nightly Coverage Scan: failed for ' + appScope + ': ' + e.message);
            errorCount++;
        }
    }

    gs.info('TestReach Nightly Coverage Scan complete. Processed: ' + processedCount + ', Errors: ' + errorCount);

})();

(function() {

    var coverageEngine = new TestReachCoverageEngine();
    var now = new GlideDateTime();
    var weekStr = now.getYear() + '-W' + now.getWeekOfYear();

    // Get all scoped apps
    var appGr = new GlideRecord('sys_app');
    appGr.addQuery('active', true);
    appGr.addQuery('scope', '!=', 'global');
    appGr.query();

    while (appGr.next()) {
        var appScope = appGr.getValue('scope') || '';
        if (!appScope) {
            continue;
        }

        // Run analysis to get current coverage
        var result = coverageEngine.analyzeAll(appScope);

        // Write trend snapshot
        var trendGr = new GlideRecord('x_snc_testreach_coverage_snapshot');
        trendGr.initialize();
        trendGr.setValue('artifact_sys_id', 'trend_' + appScope);
        trendGr.setValue('artifact_type', 'trend');
        trendGr.setValue('artifact_name', 'Weekly Trend: ' + appScope);
        trendGr.setValue('app_scope', appScope);
        trendGr.setValue('tested_by_count', result.stats.tested);
        trendGr.setValue('coverage_pct', result.stats.coverage_pct);
        trendGr.setValue('snapshot_type', 'trend');
        trendGr.setValue('snapshot_ts', now.getValue());
        trendGr.setValue('criticality', 1);

        var trendData = {
            weekly_snapshots: [{
                week: weekStr,
                pct: result.stats.coverage_pct,
                tested: result.stats.tested,
                total: result.stats.total
            }]
        };
        trendGr.setValue('trend_json', JSON.stringify(trendData));
        trendGr.setValue('findings_json', JSON.stringify({}));
        trendGr.setValue('skeleton_json', JSON.stringify({generated: false}));

        try {
            trendGr.insert();
        } catch (e) {
            gs.error('TestReach Weekly Trend Capture: insert failed for ' + appScope + ': ' + e.message);
        }
    }

    gs.info('TestReach Weekly Trend Capture complete for week ' + weekStr);

})();

(function() {

    var riskEngine = new TestReachRiskEngine();

    // Default to checking against the next major release
    var upgradeTarget = 'xanadu';

    var gaps = riskEngine.generateUpgradeGapReport(upgradeTarget);

    var criticalCount = 0;
    var highCount = 0;
    var unknownCount = 0;

    for (var i = 0; i < gaps.length; i++) {
        if (gaps[i].risk_level === 'critical') {
            criticalCount++;
        } else if (gaps[i].risk_level === 'high') {
            highCount++;
        } else if (gaps[i].risk_level === 'unknown') {
            unknownCount++;
        }
    }

    gs.info('TestReach Upgrade Gap Check complete. Total gaps: ' + gaps.length +
        ', Critical: ' + criticalCount + ', High: ' + highCount + ', Unknown: ' + unknownCount);

    if (criticalCount > 0) {
        gs.eventQueue('testreach.upgrade.gap.critical', null, criticalCount.toString(), upgradeTarget);
    }

})();
